-- [Owner, 2026-10-06] Marathi (mr) and Kannada (kn) join English, Hindi and
-- Telugu. Additive and idempotent (safe to run twice). Nothing existing is
-- removed, renamed or rewritten:
--
--   1. Every language CHECK that allowed ('en','hi','te') is re-created with
--      the same name allowing ('en','hi','te','mr','kn'). The allowed set
--      only grows, every existing row still passes, and NULL stays allowed
--      where it was. No member's language or any other row is changed.
--   2. taxonomy_terms and listing_packages gain nullable name_mr, name_kn,
--      description_mr, description_kn columns beside the _hi/_te ones.
--   3. Every taxonomy term gets its Marathi and Kannada name and description
--      (filled only where still NULL, so an operator's later edit is kept),
--      and the trade words people say in Marathi and Kannada are appended to
--      aliases (append only, like migration 026).
--   4. The privacy notice and terms of use get their Marathi and Kannada
--      text, inserted only beside an existing English version of the same
--      kind and version (seeds.sql carries the same rows for a fresh seed).
-- Words follow modules/MOD01-vyapar/GLOSSARY.md (mr / kn columns).
-- Traces to: FR04, FR44, FR48, FR53, TR042, product-owner i18n rule

-- 1. Language checks: same names, wider set ----------------------------------
DO $$
DECLARE
  c record;
BEGIN
  FOR c IN SELECT * FROM (VALUES
      ('vyapar_identity',     'members',              'language',         'members_language_check'),
      ('vyapar_listings',     'listings',             'content_language', 'listings_content_language_check'),
      ('vyapar_opportunities','opportunities',        'content_language', 'opportunities_content_language_check'),
      ('vyapar_enquiries',    'enquiry_messages',     'content_language', 'enquiry_messages_content_language_check'),
      ('vyapar_enquiries',    'partnership_requests', 'content_language', 'partnership_requests_content_language_check'),
      ('vyapar_reviews',      'reviews',              'content_language', 'reviews_content_language_check'),
      ('vyapar_privacy',      'legal_documents',      'language',         'legal_documents_language_check'),
      ('vyapar_trust_safety', 'reports',              'content_language', 'reports_content_language_check'),
      ('vyapar_trust_safety', 'appeals',              'content_language', 'appeals_content_language_check')
    ) AS t(sch, tbl, col, con)
  LOOP
    EXECUTE format('ALTER TABLE %I.%I DROP CONSTRAINT IF EXISTS %I', c.sch, c.tbl, c.con);
    EXECUTE format('ALTER TABLE %I.%I ADD CONSTRAINT %I CHECK (%I IN (''en'',''hi'',''te'',''mr'',''kn''))',
                   c.sch, c.tbl, c.con, c.col);
  END LOOP;
END $$;

-- 2. Per-language columns -----------------------------------------------------
ALTER TABLE vyapar_listings.taxonomy_terms
  ADD COLUMN IF NOT EXISTS name_mr text,
  ADD COLUMN IF NOT EXISTS name_kn text,
  ADD COLUMN IF NOT EXISTS description_mr text,
  ADD COLUMN IF NOT EXISTS description_kn text;

ALTER TABLE vyapar_listings.listing_packages
  ADD COLUMN IF NOT EXISTS name_mr text,
  ADD COLUMN IF NOT EXISTS name_kn text,
  ADD COLUMN IF NOT EXISTS description_mr text,
  ADD COLUMN IF NOT EXISTS description_kn text;

