  ('capability','sales','विक्री','ಮಾರಾಟ','ग्राहकांना उत्पादने किंवा सेवा विकतात','ಗ್ರಾಹಕರಿಗೆ ಉತ್ಪನ್ನ ಅಥವಾ ಸೇವೆಗಳನ್ನು ಮಾರಾಟ ಮಾಡುತ್ತಾರೆ',ARRAY['सेल्समन','ಸೇಲ್ಸ್','ಸೇಲ್ಸ್‌ಮ್ಯಾನ್']),
  ('capability','telecaller','टेलिकॉलर / BPO','ಟೆಲಿಕಾಲರ್ / BPO','सेल्स, सपोर्ट किंवा सर्व्हेसाठी कॉल करतात किंवा घेतात','ಸೇಲ್ಸ್, ಸಪೋರ್ಟ್ ಅಥವಾ ಸರ್ವೇಗಾಗಿ ಕಾಲ್ ಮಾಡುತ್ತಾರೆ ಅಥವಾ ಸ್ವೀಕರಿಸುತ್ತಾರೆ',ARRAY['टेलिकॉलर','टेलिकॉलिंग','ಟೆಲಿಕಾಲರ್','ಟೆಲಿಕಾಲಿಂಗ್']),
  ('capability','field_sales','फील्ड सेल्स','ಫೀಲ್ಡ್ ಸೇಲ್ಸ್','उत्पादने विकण्यासाठी दुकाने आणि ग्राहकांना भेटतात','ಉತ್ಪನ್ನ ಮಾರಾಟಕ್ಕಾಗಿ ಅಂಗಡಿಗಳು ಮತ್ತು ಗ್ರಾಹಕರನ್ನು ಭೇಟಿ ಮಾಡುತ್ತಾರೆ',ARRAY[]::text[]),
  ('capability','counter_sales','काउंटर सेल्स','ಕೌಂಟರ್ ಸೇಲ್ಸ್','दुकान किंवा शोरूमच्या काउंटरवर ग्राहकांना सेवा देतात','ಅಂಗಡಿ ಅಥವಾ ಶೋರೂಮ್ ಕೌಂಟರ್‌ನಲ್ಲಿ ಗ್ರಾಹಕರಿಗೆ ಸೇವೆ ನೀಡುತ್ತಾರೆ',ARRAY[]::text[]),
  ('capability','software','सॉफ्टवेअर डेव्हलपमेंट','ಸಾಫ್ಟ್‌ವೇರ್ ಡೆವಲಪ್‌ಮೆಂಟ್','ॲप्स, वेबसाइट्स आणि सॉफ्टवेअर सिस्टिम बनवतात','ಆ್ಯಪ್, ವೆಬ್‌ಸೈಟ್ ಮತ್ತು ಸಾಫ್ಟ್‌ವೇರ್ ಸಿಸ್ಟಮ್‌ಗಳನ್ನು ನಿರ್ಮಿಸುತ್ತಾರೆ',ARRAY['डेव्हलपर','ಡೆವಲಪರ್']),
  ('capability','react','रिॲक्ट','ರಿಯಾಕ್ಟ್','React मध्ये वेब आणि मोबाइल फ्रंट-एंड','React ನಲ್ಲಿ ವೆಬ್ ಮತ್ತು ಮೊಬೈಲ್ ಫ್ರಂಟ್-ಎಂಡ್',ARRAY[]::text[]),
  ('capability','python','पायथन','ಪೈಥಾನ್','Python मध्ये बॅक-एंड सेवा, स्क्रिप्ट आणि डेटाचे काम','Python ನಲ್ಲಿ ಬ್ಯಾಕ್-ಎಂಡ್ ಸೇವೆಗಳು, ಸ್ಕ್ರಿಪ್ಟ್‌ಗಳು ಮತ್ತು ಡೇಟಾ ಕೆಲಸ',ARRAY[]::text[]),
  ('capability','product_management','प्रॉडक्ट मॅनेजमेंट','ಪ್ರಾಡಕ್ಟ್ ಮ್ಯಾನೇಜ್‌ಮೆಂಟ್','काय बनवायचे ते ठरवतात आणि प्रॉडक्ट रोडमॅप चालवतात','ಏನು ನಿರ್ಮಿಸಬೇಕು ಎಂದು ನಿರ್ಧರಿಸಿ ಪ್ರಾಡಕ್ಟ್ ರೋಡ್‌ಮ್ಯಾಪ್ ನಡೆಸುತ್ತಾರೆ',ARRAY[]::text[]),
  ('capability','startup','स्टार्टअप','ಸ್ಟಾರ್ಟಪ್','सुरुवातीच्या टप्प्यातील कामकाज, निधी उभारणी आणि ग्रोथ','ಆರಂಭಿಕ ಹಂತದ ಕಾರ್ಯಾಚರಣೆ, ಹಣ ಸಂಗ್ರಹ ಮತ್ತು ಬೆಳವಣಿಗೆ',ARRAY[]::text[]),
  ('capability','textiles','कापड','ಜವಳಿ','कापड, साड्या आणि कपड्यांचा पुरवठा','ಬಟ್ಟೆ, ಸೀರೆಗಳು ಮತ್ತು ಉಡುಪು ಪೂರೈಕೆ',ARRAY[]::text[]),
  ('capability','tailoring','शिलाई','ಹೊಲಿಗೆ','कपडे शिवतात आणि अल्टर करतात','ಬಟ್ಟೆಗಳನ್ನು ಹೊಲಿಯುತ್ತಾರೆ ಮತ್ತು ಆಲ್ಟರ್ ಮಾಡುತ್ತಾರೆ',ARRAY['शिंपी','ಟೈಲರ್','ದರ್ಜಿ'])
)
UPDATE vyapar_listings.taxonomy_terms t
   SET name_mr        = COALESCE(t.name_mr, v.name_mr),
       name_kn        = COALESCE(t.name_kn, v.name_kn),
       description_mr = COALESCE(t.description_mr, v.description_mr),
       description_kn = COALESCE(t.description_kn, v.description_kn),
       aliases        = CASE WHEN t.kind = 'capability'
                             THEN t.aliases || ARRAY(SELECT a FROM unnest(v.aliases) a WHERE a <> '' AND NOT (a = ANY (t.aliases)))
                             ELSE t.aliases END,
       updated_at     = now()
  FROM v
 WHERE t.kind = v.kind AND t.slug = v.slug
   AND (t.name_mr IS NULL OR t.name_kn IS NULL OR t.description_mr IS NULL OR t.description_kn IS NULL
        OR (t.kind = 'capability' AND EXISTS (SELECT 1 FROM unnest(v.aliases) a WHERE a <> '' AND NOT (a = ANY (t.aliases)))));

-- 4. Privacy notice and terms of use in Marathi and Kannada ----------------------
INSERT INTO vyapar_privacy.legal_documents (kind, version, language, title, body)
SELECT d.kind, d.version, d.language, d.title, d.body
  FROM (VALUES
    ('privacy', 1, 'mr', 'व्यापार गोपनीयता सूचना',
     'आम्ही काय गोळा करतो: तुमच्या प्रोफाइलचा तपशील, तुम्ही केलेल्या पोस्ट, तुम्ही पाठवलेल्या रिक्वेस्ट आणि लिहिलेले अभिप्राय, आणि तुमची गोपनीयता सेटिंग्ज. का: शोध, रिक्वेस्ट आणि व्हेरिफिकेशन चालवण्यासाठी. कोण पाहू शकते: तुम्ही सार्वजनिक केलेलेच सदस्यांना दिसते; तुम्ही रिक्वेस्ट स्वीकारल्यानंतरच संपर्काचे मार्ग शेअर होतात. किती काळ ठेवतो: तुमचे खाते सुरू असेपर्यंत, आणि खाते हटवल्यानंतर 30 दिवस (ऑडिट आणि वादाच्या नोंदी आवश्यकतेनुसार ठेवल्या जातात). तुमचे अधिकार: गोपनीयता स्क्रीनवरून तुमची माहिती डाउनलोड करा, दुरुस्त करा, संमती मागे घ्या किंवा हटवा. तक्रार: grievance@forkhatri.example, 7 दिवसांत उत्तर मिळेल.'),
    ('privacy', 1, 'kn', 'ವ್ಯಾಪಾರ್ ಗೌಪ್ಯತಾ ಸೂಚನೆ',
     'ನಾವು ಸಂಗ್ರಹಿಸುವುದು: ನಿಮ್ಮ ಪ್ರೊಫೈಲ್ ವಿವರಗಳು, ನೀವು ಮಾಡುವ ಪೋಸ್ಟ್‌ಗಳು, ನೀವು ಕಳುಹಿಸುವ ರಿಕ್ವೆಸ್ಟ್‌ಗಳು ಮತ್ತು ಬರೆಯುವ ವಿಮರ್ಶೆಗಳು, ಹಾಗೂ ನಿಮ್ಮ ಗೌಪ್ಯತಾ ಸೆಟ್ಟಿಂಗ್‌ಗಳು. ಏಕೆ: ಹುಡುಕಾಟ, ರಿಕ್ವೆಸ್ಟ್‌ಗಳು ಮತ್ತು ವೆರಿಫಿಕೇಶನ್ ನಡೆಸಲು. ಯಾರು ನೋಡುತ್ತಾರೆ: ನೀವು ಸಾರ್ವಜನಿಕಗೊಳಿಸಿದ್ದನ್ನು ಮಾತ್ರ ಸದಸ್ಯರು ನೋಡುತ್ತಾರೆ; ನೀವು ರಿಕ್ವೆಸ್ಟ್ ಒಪ್ಪಿದ ನಂತರವೇ ಸಂಪರ್ಕ ವಿವರಗಳನ್ನು ಹಂಚಿಕೊಳ್ಳಲಾಗುತ್ತದೆ. ಎಷ್ಟು ಕಾಲ ಇಡುತ್ತೇವೆ: ನಿಮ್ಮ ಖಾತೆ ಸಕ್ರಿಯವಾಗಿರುವವರೆಗೆ, ಮತ್ತು ಖಾತೆ ಅಳಿಸಿದ ನಂತರ 30 ದಿನಗಳು (ಆಡಿಟ್ ಮತ್ತು ವಿವಾದದ ದಾಖಲೆಗಳನ್ನು ಅಗತ್ಯವಿರುವಂತೆ ಇಡಲಾಗುತ್ತದೆ). ನಿಮ್ಮ ಹಕ್ಕುಗಳು: ಗೌಪ್ಯತೆ ಪರದೆಯಿಂದ ನಿಮ್ಮ ಮಾಹಿತಿಯನ್ನು ಡೌನ್‌ಲೋಡ್ ಮಾಡಿ, ತಿದ್ದಿ, ಒಪ್ಪಿಗೆಯನ್ನು ಹಿಂಪಡೆಯಿರಿ ಅಥವಾ ಅಳಿಸಿ. ದೂರು: grievance@forkhatri.example, 7 ದಿನಗಳಲ್ಲಿ ಉತ್ತರ ನೀಡುತ್ತೇವೆ.'),
    ('terms', 1, 'mr', 'व्यापार वापराच्या अटी',
     'व्यापार म्हणजे समाजाची डिरेक्टरी आणि काम-व्यवसायाच्या पोस्टचे नेटवर्क. जे शेअर करण्याचा तुम्हाला हक्क आहे तेच पोस्ट करा; व्यापारद्वारे कधीही आगाऊ पैसे मागू नका; ब्लॉक आणि तक्रार सुविधांचा आदर करा. पैसे देऊन केलेले प्रमोशन फक्त पात्र लोकांपर्यंतची पोहोच बदलते; व्हेरिफिकेशन, प्रतिष्ठा किंवा क्रमवारी कधीही बदलत नाही. अपील: कोणत्याही मॉडरेशन निर्णयानंतर 15 दिवसांच्या आत, त्या निर्णयाच्या स्क्रीनवरून करा.'),
    ('terms', 1, 'kn', 'ವ್ಯಾಪಾರ್ ಬಳಕೆಯ ನಿಯಮಗಳು',
     'ವ್ಯಾಪಾರ್ ಎಂಬುದು ಸಮಾಜದ ಡೈರೆಕ್ಟರಿ ಮತ್ತು ಕೆಲಸ-ವ್ಯಾಪಾರದ ಪೋಸ್ಟ್‌ಗಳ ನೆಟ್‌ವರ್ಕ್. ಹಂಚಿಕೊಳ್ಳಲು ನಿಮಗೆ ಹಕ್ಕು ಇರುವುದನ್ನು ಮಾತ್ರ ಪೋಸ್ಟ್ ಮಾಡಿ; ವ್ಯಾಪಾರ್ ಮೂಲಕ ಎಂದಿಗೂ ಮುಂಗಡ ಹಣ ಕೇಳಬೇಡಿ; ಬ್ಲಾಕ್ ಮತ್ತು ದೂರು ಸೌಲಭ್ಯಗಳನ್ನು ಗೌರವಿಸಿ. ಹಣ ಕೊಟ್ಟು ಮಾಡಿದ ಪ್ರಮೋಷನ್ ಅರ್ಹ ಜನರ ನಡುವೆ ತಲುಪುವಿಕೆಯನ್ನು ಮಾತ್ರ ಬದಲಾಯಿಸುತ್ತದೆ; ವೆರಿಫಿಕೇಶನ್, ಖ್ಯಾತಿ ಅಥವಾ ಶ್ರೇಣಿಯನ್ನು ಎಂದಿಗೂ ಬದಲಾಯಿಸುವುದಿಲ್ಲ. ಮೇಲ್ಮನವಿ: ಯಾವುದೇ ಮಾಡರೇಶನ್ ತೀರ್ಮಾನದ 15 ದಿನಗಳೊಳಗೆ, ಆ ತೀರ್ಮಾನದ ಪರದೆಯಿಂದ ಸಲ್ಲಿಸಿ.')
  ) AS d(kind, version, language, title, body)
 WHERE EXISTS (SELECT 1 FROM vyapar_privacy.legal_documents e
                WHERE e.kind = d.kind AND e.version = d.version AND e.language = 'en')
ON CONFLICT (kind, version, language) DO NOTHING;
